import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Tenant API v1 — Marketplace","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Marketplace | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-marketplace"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Marketplace | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-marketplace"}]]},"headers":[],"relativePath":"api/tenant-v1-marketplace.md","filePath":"api/tenant-v1-marketplace.md","lastUpdated":1787698998000}'),r={name:"api/tenant-v1-marketplace.md"};function c(n,e,l,s,i,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-marketplace" tabindex="-1">Tenant API v1 — Marketplace <a class="header-anchor" href="#tenant-api-v1-—-marketplace" aria-label="Permalink to &quot;Tenant API v1 — Marketplace&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1/marketplace</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>marketplace.enabled</code>, plus permission middleware.</p><p>Permissions: <code>marketplace.view</code> (browse), <code>marketplace.purchase</code> (install / subscribe / remove).</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th><th>Behavior</th></tr></thead><tbody><tr><td>GET</td><td><code>/modules</code></td><td><code>marketplace.view</code></td><td>Paginated published catalog (<code>search</code>, <code>category_id</code>) + per-row install flags</td></tr><tr><td>GET</td><td><code>/modules/{module}</code></td><td><code>marketplace.view</code></td><td>Detail + install state for the current workspace</td></tr><tr><td>POST</td><td><code>/modules/{module}/purchase</code></td><td><code>marketplace.purchase</code></td><td>Install free module or start paid checkout</td></tr><tr><td>POST</td><td><code>/modules/{module}/confirm-checkout</code></td><td><code>marketplace.purchase</code></td><td>Confirm return from payment gateway</td></tr><tr><td>POST</td><td><code>/modules/{module}/cancel</code></td><td><code>marketplace.purchase</code></td><td>Remove / cancel a non-core installed module</td></tr></tbody></table><h3 id="list-row-extras" tabindex="-1">List row extras <a class="header-anchor" href="#list-row-extras" aria-label="Permalink to &quot;List row extras&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>already_installed</code></td><td>Active or trial subscription for this workspace</td></tr><tr><td><code>purchase_pending</code></td><td>Pending checkout not yet activated</td></tr><tr><td><code>version</code></td><td>Catalog display version (semver metadata)</td></tr><tr><td><code>is_billable</code></td><td>Paid module (SPA badge <strong>Billable</strong> when not installed)</td></tr></tbody></table><p>SPA badge priority: <strong>Installed</strong> → <strong>Pending</strong> → <strong>Billable</strong> → <strong>Available</strong> (free, not installed). Do not label free opt-in modules as “Included”.</p><h3 id="display-currency-conversion" tabindex="-1">Display currency conversion <a class="header-anchor" href="#display-currency-conversion" aria-label="Permalink to &quot;Display currency conversion&quot;">​</a></h3><p>Catalog prices are stored in <code>modules.currency</code> (typically <strong>USD</strong>). Tenant list/detail responses convert <code>monthly_price</code>, <code>yearly_price</code>, and <code>setup_fee</code> into the <strong>workspace currency</strong> (<code>tenants.currency</code>) for display only.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>monthly_price</code> / <code>yearly_price</code> / <code>setup_fee</code></td><td>Amount in <code>currency</code> (tenant currency when conversion succeeds)</td></tr><tr><td><code>currency</code></td><td>Display currency for the amounts above</td></tr><tr><td><code>base_*_price</code> / <code>base_currency</code></td><td>Original catalog amounts / currency</td></tr><tr><td><code>billed_currency</code></td><td>Currency charged at checkout (catalog / Stripe Price — usually USD)</td></tr><tr><td><code>exchange_rate</code> / <code>exchange_rate_at</code></td><td>Mid-market rate used for the conversion</td></tr><tr><td><code>price_converted</code></td><td><code>true</code> when amounts were converted from the catalog currency</td></tr></tbody></table><p>If the FX provider is unavailable, amounts stay in the catalog currency (<code>price_converted: false</code>). <strong>Checkout still charges the mapped Stripe (or gateway) Price in <code>billed_currency</code></strong> — conversion is display-only.</p><p>Rates: <code>CurrencyConversionService</code> → <code>open.er-api.com</code> (configurable via <code>CURRENCY_FX_*</code> env), cached (~12h).</p><h3 id="detail-payload-extras" tabindex="-1">Detail payload extras <a class="header-anchor" href="#detail-payload-extras" aria-label="Permalink to &quot;Detail payload extras&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>already_installed</code></td><td>Active or trial subscription for this workspace</td></tr><tr><td><code>purchase_pending</code></td><td>Pending checkout not yet activated</td></tr><tr><td><code>subscription_status</code> / <code>subscription_source</code></td><td>Current row when present</td></tr><tr><td><code>can_cancel</code></td><td>Tenant may remove it now (not core-included, no blocking dependents)</td></tr><tr><td><code>required_modules</code> / <code>optional_modules</code> / <code>missing_required_modules</code></td><td><strong>Dependencies</strong> — modules this one needs (upstream)</td></tr><tr><td><code>blocking_dependents</code></td><td><strong>Dependents</strong> — installed modules that hard-depend on this one (downstream; blocks remove)</td></tr></tbody></table><p>Dependency summaries (<code>required_modules</code>, <code>optional_modules</code>, <code>missing_required_modules</code>) include pricing and install flags so the SPA can offer <strong>Install</strong> / <strong>Subscribe</strong> on a missing required module without an extra detail round-trip:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code> / <code>name</code> / <code>slug</code></td><td>Catalog identity</td></tr><tr><td><code>is_billable</code> / <code>is_default_included</code></td><td>Commercial / core flags</td></tr><tr><td><code>already_installed</code> / <code>purchase_pending</code></td><td>Workspace install state</td></tr><tr><td><code>monthly_price</code> / <code>yearly_price</code> / <code>currency</code></td><td>Display amounts (workspace currency when FX succeeds)</td></tr><tr><td><code>base_*</code> / <code>billed_currency</code> / <code>price_converted</code></td><td>Same display-FX shape as list rows</td></tr></tbody></table><p><code>blocking_dependents</code> remains <code>{ id, name, slug }</code> only.</p><p>UI copy must keep these directions distinct: “no dependencies” means nothing upstream is required; dependents (e.g. Meetings → Calendar) still block remove until those modules are removed first.</p><h3 id="cancel-rules" tabindex="-1">Cancel rules <a class="header-anchor" href="#cancel-rules" aria-label="Permalink to &quot;Cancel rules&quot;">​</a></h3><ul><li>Default-included core modules (today: Leads, Tasks) cannot be cancelled by tenants.</li><li>Hard dependents must be removed first (e.g. remove Meetings before Calendar).</li><li>Cancel sets status <code>cancelled</code>, clears entitlements immediately, and cancels any live provider subscription.</li><li>Response includes refreshed <code>modules</code> entitlement slugs for the workspace.</li></ul><p>See <a href="/developer-guide/entitlements">Entitlements</a> for install / cancel policy.</p>',23)])])}const h=t(r,[["render",c]]);export{m as __pageData,h as default};
